<?php
namespace App\Services;
use App\Models\Cita; use App\Repositories\CitaRepository; use App\Repositories\CitaCatalogoRepository; use Illuminate\Support\Facades\DB; use Illuminate\Validation\ValidationException; use MongoDB\BSON\ObjectId;
class CitaService {
 public function __construct(private CitaRepository $repo,private CitaCatalogoRepository $catalogos){}
 public function validarId(string $id):void {if(!preg_match('/\A[a-fA-F0-9]{24}\z/',$id))throw ValidationException::withMessages(['id'=>['El identificador debe ser un ObjectId válido de 24 caracteres hexadecimales.']]);}
 private function validarReferencias(array $d):void {foreach(['CodigoPaciente'=>'paciente','CodigoColaborador'=>'colaborador','CodigoSucursal'=>'sucursal','CodigoEspecialidad'=>'especialidad'] as $k=>$tipo) if(isset($d[$k])&&!$this->catalogos->existe($tipo,strtolower($d[$k]))) throw ValidationException::withMessages([$k=>["La referencia {$k} no existe."]]); foreach(($d['detalles']??[]) as $i=>$linea) if(!empty($linea['CodigoProducto'])&&!$this->catalogos->existe('producto',strtolower($linea['CodigoProducto']))) throw ValidationException::withMessages(["detalles.$i.CodigoProducto"=>['El producto indicado no existe.']]);}
 private function prepararDetalles(array $lineas):array {return array_map(function($l){if(!empty($l['CodigoProducto']))$l['CodigoProducto']=new ObjectId(strtolower((string)$l['CodigoProducto']));$l['FechaRegistro']=$l['FechaRegistro']??now();$l['Estado']=$l['Estado']??'Activo';foreach(['CodigoProducto','SubtipoDetalle','Dosis','Frecuencia','Duracion','Indicaciones','Resultado','Cantidad'] as $k)$l[$k]??=null;return $l;},$lineas);}
 private function prepararReferencias(array $d):array { foreach(['CodigoPaciente','CodigoColaborador','CodigoSucursal','CodigoEspecialidad'] as $k) if(isset($d[$k])) $d[$k]=new ObjectId(strtolower((string)$d[$k])); return $d; }
 private function enriquecer($citas){$arr=collect($citas)->map(fn($c)=>$c->toArray())->all();$desc=$this->catalogos->descripciones($arr);foreach($arr as &$c){$c['id']=(string)($c['_id']??'');foreach($desc as $k=>$map){$raw=$c[$k]??null;$c[$k]=$raw===null?null:(string)$raw;$c['_'.$k.'Descripcion']=$map[(string)($c[$k]??'')]??null;}unset($c['_id']);}return $arr;}
 public function listar(array $f){$p=$this->repo->listar($f);$p->setCollection(collect($this->enriquecer($p->getCollection())));return $p;}
 public function buscar(array $f){return $this->listar($f);}
 public function catalogos(){return ['colaboradores'=>$this->catalogos->colaboradores(),'especialidades'=>$this->catalogos->especialidades()];}
 public function obtener(string $id):array{$this->validarId($id);$c=$this->repo->obtener(strtolower($id));$a=$this->enriquecer([$c])[0];$a['detalles']=$this->repo->detalles((string)$c->getKey())->map(function($d){$x=$d->toArray();$x['id']=(string)$d->getKey();foreach(['CodigoCitaConsulta','CodigoProducto'] as $k)if(isset($x[$k]))$x[$k]=(string)$x[$k];unset($x['_id']);return $x;});return $a;}
 public function crear(array $d):array{$this->validarReferencias($d);$lineas=$this->prepararDetalles($d['detalles']);unset($d['detalles']);$c=DB::connection('mongodb')->transaction(function()use($d,$lineas){$c=$this->repo->crear($this->prepararReferencias($d));$this->repo->reemplazarDetalles((string)$c->getKey(),$lineas);return $c;});return $this->obtener((string)$c->getKey());}
 public function actualizar(string $id,array $d,bool $completo):array{$this->validarId($id);$this->repo->obtener(strtolower($id));$this->validarReferencias($d);$lineas=$d['detalles']??null;unset($d['detalles']);if($completo){foreach(Cita::OPCIONALES as $k)$d[$k]??=null;} $c=DB::connection('mongodb')->transaction(function()use($id,$d,$lineas){$c=$this->repo->actualizar(strtolower($id),$this->prepararReferencias($d));if($lineas!==null)$this->repo->reemplazarDetalles((string)$c->getKey(),$this->prepararDetalles($lineas));return $c;});return $this->obtener((string)$c->getKey());}
 public function eliminar(string $id):void{$this->validarId($id);DB::connection('mongodb')->transaction(function()use($id){$this->repo->obtener(strtolower($id));$this->repo->eliminarDetalles(strtolower($id));$this->repo->eliminar(strtolower($id));});}
}
